489	    private String parseStatusFromHtml(String html, String trackingNumber) {
490	        try {
491	            Document doc = Jsoup.parse(html);
492	            Elements rows = doc.select(STATUS_SELECTOR);
493	
494	            if (rows.isEmpty()) {
495	                log.warn("배송 상태 테이블이 비어 있음: 운송장={}", trackingNumber);
496	                throw new Xpb98Exception(
497	                        Xpb98ErrorCode.TRACKING_HTML_PARSE_ERROR,
498	                        "배송 정보가 없습니다. 운송장 번호를 확인해주세요: " + trackingNumber
499	                );
500	            }
501	
502	
503	            String statusText = rows.last().select("td").get(4).text().trim();
504	
505	            if (statusText.isEmpty()) {
506	                log.warn("배송 상태 텍스트가 비어 있음: 운송장={}", trackingNumber);
507	                throw new Xpb98Exception(
508	                        Xpb98ErrorCode.TRACKING_HTML_PARSE_ERROR,
509	                        "배송 상태 정보를 찾을 수 없습니다."
510	                );
511	            }
512	
513	            return statusText;
514	
515	        } catch (IndexOutOfBoundsException e) {
516	            log.error("HTML 파싱 중 인덱스 오류: 운송장={}, 오류={}", trackingNumber, e.getMessage(), e);
517	            throw new Xpb98Exception(
518	                    Xpb98ErrorCode.TRACKING_HTML_PARSE_ERROR,
519	                    "배송 상태 정보 파싱 실패: 예상한 형식과 다릅니다.",
520	                    e
521	            );
522	        } catch (Exception e) {
523	            if (e instanceof Xpb98Exception) {
524	                throw (Xpb98Exception) e;
525	            }
526	
527	            log.error("HTML 파싱 중 오류 발생: 운송장={}, 오류={}", trackingNumber, e.getMessage(), e);
528	            throw new Xpb98Exception(
529	                    Xpb98ErrorCode.TRACKING_HTML_PARSE_ERROR,
530	                    "배송 상태 정보 파싱 실패: " + e.getMessage(),
531	                    e
532	            );
533	        }
534	    }
