    private final Xdg64EventProducer orderEventProducer;











    @PostMapping("/{orderId}/process-payment-shipment")
    public ResponseEntity<ResponseDto<Map<String, Object>>> processPaymentAndShipment(
            @PathVariable("orderId") Long orderId,
            @RequestBody @Valid Xrt49RequestDto requestDto
    ) {

        String email = SecurityUtils.extractAndValidateEmailForOrder("결제 및 배송 처리");

        log.info("사용자 [{}]가 주문(ID: {})의 결제 및 배송 처리를 요청합니다.", email, orderId);

        try {

            orderEventProducer.sendOrderProcessingEvent(orderId, email, requestDto);


            Map<String, Object> responseData = new HashMap<>();
            responseData.put("orderId", orderId);
            responseData.put("status", "PROCESSING");
            responseData.put("message", "주문이 접수되었습니다. 결제를 처리하고 있습니다.");
            responseData.put("estimatedProcessingTime", "1-3분");
            responseData.put("websocketTopic", "/topic/order/" + orderId);
            responseData.put("statusCheckUrl", "/api/orders/" + orderId + "/status");

            log.info("주문 처리 이벤트 발행 완료: 주문ID={}, 사용자={}", orderId, email);


            return ResponseEntity.status(HttpStatus.ACCEPTED)
                    .body(ResponseDto.success(responseData, "주문 처리가 시작되었습니다. 처리 완료 시 알림을 받으실 수 있습니다."));










    @PostMapping("/instant")
    public ResponseEntity<ResponseDto<Long>> createInstantOrderBid(@RequestBody @Valid Xpj49RequestDto requestDto) {

        String email = SecurityUtils.extractAndValidateEmailForOrderBid("즉시 구매 입찰 생성");

        log.info("사용자 [{}]가 판매 입찰(ID: {})에 대한 즉시 구매를 요청합니다. 창고 보관 여부: {}",
                email, requestDto.getSaleBidId(), requestDto.isWarehouseStorage());


        Xbf54RequestDto paymentRequest = enrichPaymentRequest(requestDto.getPaymentRequest(), email);


        Long orderId = orderBidCommandService.createInstantOrderBid(
                email,
                requestDto.getSaleBidId(),
                requestDto.getAddressId(),
                requestDto.isWarehouseStorage(),
                paymentRequest
        ).getId();

        return ResponseEntity.ok(ResponseDto.success(orderId, "즉시 구매가 성공적으로 처리되었습니다."));
    }








    private Xbf54RequestDto enrichPaymentRequest(Xbf54RequestDto paymentRequest, String email) {
        paymentRequest.setUserEmail(email);
        paymentRequest.setOrderId(null);
        return paymentRequest;
    }
}

